import java.util.Scanner;

public class Main {
    static final int MAXN = 1000111;
    static final long MOD = 1000000007;

    static long[] visited = new long[MAXN];
    static long[] freqCount = new long[MAXN];

    static long powerMod(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(powerMod(p, p - 1));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(powerMod(p, p));
            sc.close();
            return;
        }

        for (int i = 0; i < p; i++) {
            visited[i] = 0;
            freqCount[i] = 0;
        }

        for (int start = 1; start < p; start++) {
            if (visited[start] != 0) continue;
            long u = start, cycleLength = 0;
            while (visited[(int) u] == 0) {
                visited[(int) u] = 1;
                u = (u * k) % p;
                cycleLength++;
            }
            freqCount[(int) cycleLength]++;
        }

        long result = 1;
        for (int length = 1; length <= p - 1; length++) {
            if (freqCount[length] == 0) continue;
            long tmp = powerMod((length * freqCount[length] + 1) % MOD, (int) freqCount[length]);
            result = (result * tmp) % MOD;
        }

        System.out.println(result);
        sc.close();
    }
}
